    },
    {
      "element_id": "prisma_2020_6_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No study registers, regulatory databases, or online repositories (other than bibliographic databases) were reported as searched."
