    {
      "element_id": "prisma_2020_6_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No websites or search engines other than Google Scholar (a bibliographic source) were reported; no URLs given, and no other online sources were described."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No organisations or manufacturers were reported as contacted to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No individuals were contacted to identify studies (contact with investigators mentioned only for missing data clarification, not identification)."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No reference list searching was reported."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No backward or forward citation searching was reported."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No journals or conference proceedings were directly consulted; conference papers were explicitly excluded."
    }
  ],
  "confidence": 85
}

