    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not state whether all compatible results (measures, time points, analyses) within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Conditional; since the manuscript does not indicate that only a subset of compatible results was sought, no selection process needs describing."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Conditional; no evidence of changes to outcome definitions or importance during the review is reported."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Conditional; no evidence of changes to result-selection processes is reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although a primary outcome is named, no rationale for prioritising it or statement of outcomes most important for interpreting conclusions is provided."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
