{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The Newcastle-Ottawa quality assessment scale (NOS) adapted for observational studies was used to assess the quality of each original study [29].",
      "reason": "The risk-of-bias tool (NOS adapted for observational studies) is explicitly named."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The quality assessment tool is divided into three sections. The first section concentrated on each original study's methodological quality, such as objectives, sample size, and sampling technique... The tool's second section evaluates study comparability... The third section of the tool evaluates the outcome measures and data analysis.",
      "reason": "The domains/components of the NOS (selection/methodological quality, comparability, outcome) and their star scoring are described."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The NOS leveled a study as good if the score is 7-8, and very good for scores 9-10. The review and meta-analysis included studies with a score of 5 or higher.",
      "reason": "Overall quality judgement categories and the score thresholds/rules used to derive them are reported."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "The Newcastle-Ottawa quality assessment scale (NOS) adapted for observational studies was used",
      "reason": "An adaptation is mentioned ('adapted for observational studies'), but the specific modifications made to the tool are not described."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No newly developed risk-of-bias tool was used; an existing tool (NOS) was applied."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The articles' quality was assessed by three authors (MBY, CT and DGD). The authors then compared the scores assigned to each study. Discrepancies in ratings were resolved through consensus.",
      "reason": "Number of reviewers (three), comparison of ratings, and consensus-based disagreement resolution are reported; independence is implied by comparing independently assigned scores."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of processes to obtain or confirm risk-of-bias information from study investigators; such contact was only described for missing data extraction, not risk of bias."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools were reported for risk-of-bias assessment; assessment was done manually by authors."
    }
  ],
  "confidence": 92
}

{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_24",
      "quote": "Only studies reported both adjusted odds ratio (AOR) with 95% confidence interval (CI) were included to identify pooled effect of predictors for MRPs.",
      "reason": "Effect measures are specified for each outcome: pooled prevalence with 95% CI for prevalence outcomes (text_16: 'pooled national prevalence of MRPs was estimated using a random-effects meta-analysis model') and adjusted odds ratio (AOR) with 95% CI for predictors (text_24)."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No thresholds or ranges for interpreting effect sizes (e.g., what constitutes a large effect) are reported; only a p<0.05 significance threshold is given, which does not address effect size interpretation."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence that synthesized results were re-expressed using another effect measure; prevalence and AOR were used directly as reported or computed from primary studies."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The choice of effect measures (prevalence, AOR) is stated but no rationale or justification for choosing them is provided."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "The titles and abstracts of studies retrieved and those from unpublished sources were screened to identify studies that satisfy the inclusion criteria. Then, the full text of potentially eligible studies was assessed.",
      "reason": "The manuscript describes the process for deciding study eligibility: title/abstract screening against inclusion criteria, full-text assessment of potentially eligible studies, with eligibility criteria detailed in text_10/text_12 and illustrated in the PRISMA flow diagram (text_17, figure_9). As the review has a single synthesis (pooled prevalence and predictors), no tabulation against multiple planned synthesis groups was needed."
    }
  ],
  "confidence": 85
